const week = {
  days: ["Mon", "Tue", "Wed"],
  [Symbol.iterator]() {
    const days = this.days;
    let i = 0;
    return {
      next: () => (i < days.length ? { value: days[i++], done: false } : { value: undefined, done: true }),
    };
  },
};

const [first] = week;
week.days.push("Thu");
console.log(first);
console.log([...week].join(","));
console.log([...week].length);
